#!/usr/bin/env node
// Rebrand the agents/ sub-package from legacy upstream identities
// (nirholas / defi-agents / @nirholas/ai-agents-library / clawdos / openclawd.biz)
// to the canonical Solana Clawd brand served at x402.wtf.
//
// - Phase 1: normalize every src/*.json agent so it is Solana Clawd owned.
// - Phase 2: text sweep across metadata, docs, skills, and scripts.
//
// Idempotent: safe to re-run. Does NOT touch node_modules, .git, public/,
// locales/, or lockfiles (public/ + catalog are regenerated by build-catalog.cjs).
//
// Run: node scripts/rebrand-to-solana-clawd.mjs

import { readdir, readFile, writeFile, stat } from 'node:fs/promises';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..');
const SRC_DIR = join(ROOT, 'src');
const SELF_SCRIPT = join(ROOT, 'scripts', 'rebrand-to-solana-clawd.mjs');

// Canonical brand constants.
const BRAND = {
  github: 'https://github.com/x402agent/solana-clawd',
  owner: 'x402agent',
  repo: 'solana-clawd',
  npm: '@solana-clawd/agents',
  host: 'https://x402.wtf',
  author: 'solana-clawd',
  mcpName: 'io.github.x402agent/solana-clawd-agents',
};

// Authors that are already considered Solana Clawd owned.
const OWNED_AUTHORS = new Set(['solana-clawd', 'x402agent', 'openclawd', 'OpenClawd']);

// Bounded sweep so we never touch node_modules or generated/binary assets.
const SWEEP_DIRS = [
  'src',
  'docs',
  'scripts',
  'schema',
  'templates',
  '.well-known',
  '.github',
  'skills',
];

const SWEEP_FILES = [
  'README.md',
  'README.zh-CN.md',
  'package.json',
  'AGENTS.md',
  'CLAUDE.md',
  'GEMINI.md',
  'CHANGELOG.md',
  'CITATION.cff',
  'CODE_OF_CONDUCT.md',
  'CONTRIBUTING.md',
  'SECURITY.md',
  'humans.txt',
  'meta.json',
  'server.json',
  'agent-template.json',
  'agent-template-full.json',
  'agent-template-attested.json',
  'agents-manifest.json',
  'tsconfig.json',
  'vercel.json',
];

const SKIP_EXT = new Set([
  '.png', '.jpg', '.jpeg', '.gif', '.svg', '.ico', '.webp', '.pdf',
  '.lock', '.woff', '.woff2', '.ttf', '.eot',
]);

const SKIP_DIR_PARTS = new Set([
  'node_modules', '.git', 'dist', 'build', '.vercel', '.next', '.turbo',
  'public', 'locales',
]);

// Ordered replacements: most specific first so partial tokens never leak.
const TEXT_REPLACEMENTS = [
  // npm package name.
  [/@nirholas\/ai-agents-library/g, BRAND.npm],

  // GitHub repo URLs (specific repos first).
  [/github\.com\/nirholas\/(?:defi-agents|ai-agents-library)(\.git)?/g, `github.com/${BRAND.owner}/${BRAND.repo}$1`],
  [/github\.com\/clawdos\/clawd-ai-agents(\.git)?/g, `github.com/${BRAND.owner}/${BRAND.repo}$1`],
  [/github\.com\/clawdsolana\/OpenClawd/g, `github.com/${BRAND.owner}/${BRAND.repo}`],

  // MCP server identifier.
  [/io\.github\.nirholas\/defi-agents/g, BRAND.mcpName],

  // Serving domains -> canonical x402.wtf.
  [/https?:\/\/agents\.openclawd\.biz/g, BRAND.host],
  [/https?:\/\/chat-agents\.clawdos\.com/g, BRAND.host],
  [/https?:\/\/clawd\.io/g, BRAND.host],

  // Remaining bare GitHub owner.
  [/github\.com\/nirholas\b/g, `github.com/${BRAND.owner}`],

  // Author handle / contact.
  [/nirholasi@github\.io/g, 'agents@x402.wtf'],
  [/\bnirholas\b/g, BRAND.owner],

  // Project token used in prose / ids.
  [/\bdefi-agents\b/g, 'solana-clawd-agents'],

  // Straggler non-brand agent author.
  [/"author":\s*"8bitsats"/g, `"author": "${BRAND.author}"`],
];

// ---------- Phase 1: agent ownership normalization ----------

function normalizeAgent(entry) {
  let changed = false;

  if (!OWNED_AUTHORS.has(entry.author)) {
    entry.author = BRAND.author;
    changed = true;
  }

  if (
    typeof entry.homepage === 'string' &&
    !entry.homepage.startsWith(BRAND.github) &&
    /github\.com\/(nirholas|clawdos|clawdsolana|8bitsats)/.test(entry.homepage)
  ) {
    entry.homepage = BRAND.github;
    changed = true;
  }

  entry.meta = entry.meta ?? {};
  const tags = Array.isArray(entry.meta.tags) ? [...entry.meta.tags] : [];
  for (const tag of ['clawd', 'solana-clawd']) {
    if (!tags.includes(tag)) {
      tags.push(tag);
      changed = true;
    }
  }
  entry.meta.tags = tags;

  return changed;
}

async function phaseOneOwnership() {
  let files;
  try {
    files = (await readdir(SRC_DIR)).filter((n) => n.endsWith('.json'));
  } catch {
    console.log('Phase 1: no src/ dir, skipping');
    return;
  }

  let normalized = 0;
  for (const name of files) {
    const file = join(SRC_DIR, name);
    const raw = await readFile(file, 'utf8');
    let entry;
    try {
      entry = JSON.parse(raw);
    } catch {
      console.warn(`  skip (invalid json) ${name}`);
      continue;
    }
    if (normalizeAgent(entry)) {
      await writeFile(file, `${JSON.stringify(entry, null, 2)}\n`, 'utf8');
      normalized += 1;
    }
  }

  console.log(`Phase 1: normalized ownership on ${normalized}/${files.length} agents`);
}

// ---------- Phase 2: text sweep ----------

function shouldSkipPath(path) {
  if (path === SELF_SCRIPT) return true;
  for (const part of path.split('/')) {
    if (SKIP_DIR_PARTS.has(part)) return true;
  }
  for (const ext of SKIP_EXT) {
    if (path.endsWith(ext)) return true;
  }
  return false;
}

async function walk(dir, out) {
  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    const full = join(dir, entry.name);
    if (shouldSkipPath(full)) continue;
    if (entry.isDirectory()) await walk(full, out);
    else if (entry.isFile()) out.push(full);
  }
}

function applyReplacements(content) {
  let next = content;
  for (const [pattern, replacement] of TEXT_REPLACEMENTS) {
    next = next.replace(pattern, replacement);
  }
  return next;
}

async function phaseTwoTextSweep() {
  const files = [];
  for (const dir of SWEEP_DIRS) await walk(join(ROOT, dir), files);
  for (const name of SWEEP_FILES) {
    const full = join(ROOT, name);
    try {
      await stat(full);
      if (!shouldSkipPath(full)) files.push(full);
    } catch {
      // missing — skip
    }
  }

  let scanned = 0;
  let changed = 0;
  for (const file of files) {
    scanned += 1;
    let content;
    try {
      content = await readFile(file, 'utf8');
    } catch {
      continue;
    }
    const next = applyReplacements(content);
    if (next !== content) {
      await writeFile(file, next, 'utf8');
      changed += 1;
    }
  }

  console.log(`Phase 2: scanned ${scanned} files, rewrote ${changed}`);
}

async function main() {
  await phaseOneOwnership();
  await phaseTwoTextSweep();
  console.log('\nRebrand complete. Run build-catalog.cjs to regenerate public/ + catalog.');
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
